const r = phi.js(() => {
  const el = document.querySelector('[href="#card329d5bf173ae4b27863d81979e8a7dc2"]');
  if (!el) return { found: false };
  const card = document.getElementById('card329d5bf173ae4b27863d81979e8a7dc2');
  const info = { hrefOk: true, linkCls: el.className.toString(), expanded: el.getAttribute('aria-expanded') };
  if (card) { info.cardCls = card.className.toString(); info.cardText = card.innerText.trim().slice(0, 2000); info.cardHTML = card.innerHTML.slice(0, 3000); }
  else { const p = el.closest('div'); info.parentCls = p && p.className.toString(); info.parentText = p && p.innerText.trim().slice(0,2000); }
  return info;
});
return r;

