const sel = 'a[href="#card329d5bf173ae4b27863d81979e8a7dc2"]';
const el = phi.query(sel, { limit: 1 });
const obs = phi.observe({ within: ".accordion, .card, [id*='card329']", maxElements: 60 });
const info = phi.js(() => {
  const l = document.querySelector('a[href="#card329d5bf173ae4b27863d81979e8a7dc2"]');
  if (!l) return { found: false };
  l.scrollIntoView({ block: "center" });
  const r = l.getBoundingClientRect();
  const top = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
  return { rect: { x: r.x, y: r.y, w: r.width, h: r.height }, topTag: top && top.tagName, topCls: top && top.className && top.className.toString(), isSelfOrChild: top ? (l === top || l.contains(top)) : null, text: l.innerText.trim() };
});
return { linkCount: el.total, obsNodes: obs.nodes.map(n => ({ ref: n.ref, role: n.role, name: n.name })), info };

