const cands = ["/lost-and-found","/lost-and-found-form","/lost-item-form","/lostandfound","/lost-item","/lost-items","/lostandfoundform"];
const statuses = phi.js(async (list) => {
  const out = [];
  for (const p of list) {
    try {
      const r = await fetch(p, { redirect: "manual" });
      out.push({ p, status: r.status, type: r.type, loc: r.headers.get("location") });
    } catch (e) { out.push({ p, err: String(e).slice(0,80) }); }
  }
  return out;
}, [cands]);
return { url: phi.observe().url, rel: rel.slice(0,40), statuses };

